248	    private static boolean isBlank(String value) {
249	        return value == null || value.isBlank();
250	    }
251	
252	    /**
253	     * Normalizes a street address into the canonical form stored on and returned for a newly
254	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
255	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
256	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
257	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
258	     * value is what gets persisted, echoed back, and used for every address comparison (household
259	     * duplicate detection and the shared household identifier).
260	     *
261	     * @param rawAddress the address value as supplied by the client
262	     * @return the normalized address (possibly empty, never {@code null})
263	     */
264	    private static String normalizeAddress(String rawAddress) {
265	        if (rawAddress == null) {
266	            return "";
267	        }
268	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
269	        if (collapsed.isEmpty()) {
270	            return "";
271	        }
272	        String[] tokens = collapsed.split(" ");
273	        StringBuilder sb = new StringBuilder(collapsed.length());
274	        for (int i = 0; i < tokens.length; i++) {
275	            String token = tokens[i];
276	            switch (token) {
277	                case "ST" -> token = "STREET";
278	                case "RD" -> token = "ROAD";
279	                case "AVE" -> token = "AVENUE";
280	                default -> { }
281	            }
282	            if (i > 0) {
283	                sb.append(' ');
284	            }
285	            sb.append(token);
286	        }
287	        return sb.toString();
288	    }
289	
290	    /**
291	     * Builds the customer code assigned to a newly created owner. The code is formatted
292	     * {@code <LAST3>-<NNNN>} where {@code LAST3} is the upper-cased first three letters of
293	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal
294	     * to one more than the current number of owners (e.g. {@code SMI-0007}).
295	     *
296	     * @param lastName the last name of the owner being created
297	     * @return the customer code to assign
298	     */
299	    private String nextCustomerCode(String lastName) {
300	        StringBuilder last3 = new StringBuilder();
301	        for (int i = 0; i < lastName.length() && last3.length() < 3; i++) {
302	            char c = lastName.charAt(i);
303	            if (Character.isLetter(c)) {
304	                last3.append(Character.toUpperCase(c));
305	            }
306	        }
307	        long sequence = this.clinicService.findAllOwners().size() + 1L;
308	        return String.format("%s-%04d", last3, sequence);
309	    }
310	
311	    /**
312	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
313	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
314	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
315	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
316	     *
317	     * @param rawTelephone the telephone value as supplied by the client
318	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
319	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
320	     */
321	    private static String normalizeTelephone(String rawTelephone) {
322	        if (rawTelephone == null) {
323	            throw new InvalidTelephoneException(rawTelephone);
324	        }
325	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
326	        String e164;
327	        if (cleaned.startsWith("+")) {
328	            String digits = cleaned.substring(1);
329	            if (!digits.matches("[0-9]+")) {
330	                throw new InvalidTelephoneException(rawTelephone);
331	            }
332	            e164 = "+" + digits;
333	        } else {
334	            if (!cleaned.matches("[0-9]+")) {
335	                throw new InvalidTelephoneException(rawTelephone);
336	            }
337	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
338	            e164 = "+61" + national;
339	        }
340	        int digitCount = e164.length() - 1;
341	        if (digitCount < 8 || digitCount > 15) {
342	            throw new InvalidTelephoneException(rawTelephone);
343	        }
344	        return e164;
345	    }
346	
347	    /**
348	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
349	     * telephones are themselves E.164, so the values are compared directly.
350	     *
351	     * @param e164Telephone the E.164 telephone of the owner being created
352	     * @return {@code true} if another owner already has the same E.164 telephone
353	     */
354	    private boolean isTelephoneInUse(String e164Telephone) {
355	        return this.clinicService.findAllOwners().stream()
356	            .map(Owner::getTelephone)
357	            .filter(existing -> existing != null)
358	            .anyMatch(e164Telephone::equals);
359	    }
360	
361	    /**
362	     * Determines whether any existing owner already shares a household with the owner being created,
363	     * i.e. has both the same last name and the same address. Both fields are compared
364	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
365	     *
366	     * @param lastName the last name of the owner being created
367	     * @param address the address of the owner being created
368	     * @return {@code true} if another owner already has the same last name and address
369	     */
370	    private boolean isHouseholdInUse(String lastName, String address) {
371	        String normalizedLastName = normalizeIdentity(lastName);
372	        String normalizedAddress = normalizeIdentity(address);
373	        return this.clinicService.findAllOwners().stream()
374	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
375	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
376	    }
377	
378	    /**
379	     * Assigns the owner being created to the household identified by the given last name and
380	     * address and returns the household's stable shared identifier. The identifier is derived
381	     * deterministically from the normalized last name and address, so every member of the same
382	     * household resolves to the same value regardless of creation order. Any existing member that
383	     * does not yet carry the identifier is back-filled so all household members share it.
384	     *
385	     * @param lastName the last name of the owner being created
386	     * @param address the address of the owner being created
387	     * @return the stable household identifier shared by all members of the household
388	     */
389	    private String joinHousehold(String lastName, String address) {
390	        String householdId = householdIdFor(lastName, address);
391	        String normalizedLastName = normalizeIdentity(lastName);
392	        String normalizedAddress = normalizeIdentity(address);
393	        for (Owner existing : this.clinicService.findAllOwners()) {
394	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
395	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
396	                && !householdId.equals(existing.getHouseholdId())) {
397	                existing.setHouseholdId(householdId);
398	                this.clinicService.saveOwner(existing);
399	            }
400	        }
401	        return householdId;
402	    }
403	
404	    /**
405	     * Derives the stable household identifier for a given last name and address. The value is the
406	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
407	     * address, so it is stable across calls and identical for every member of the household.
408	     *
409	     * @param lastName the last name of the household
410	     * @param address the address of the household
411	     * @return the stable household identifier
412	     */
413	    private static String householdIdFor(String lastName, String address) {
414	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
415	        try {
416	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
417	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
418	            StringBuilder sb = new StringBuilder(digest.length * 2);
419	            for (byte b : digest) {
420	                sb.append(String.format("%02x", b));
421	            }
422	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
423	        }
424	        catch (java.security.NoSuchAlgorithmException e) {
425	            throw new IllegalStateException("SHA-256 not available", e);
426	        }
427	    }
428	
429	    /**
430	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
431	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
432	     * single space, and the result is lower-cased.
433	     *
434	     * @param value the raw field value
435	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
436	     */
437	    private static String normalizeIdentity(String value) {
438	        if (value == null) {
439	            return "";
440	        }
441	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
442	    }
443	}
